#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import csv
import gzip
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from decimal import Decimal
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    t = b.decode("utf-8-sig")
    return t


def lines_of(text):
    return [l for l in text.replace("\r\n", "\n").replace("\r", "\n").split("\n") if l.strip() != ""]


def all_files(d):
    out = []
    if not os.path.isdir(d):
        return out
    for r, _, fs in os.walk(d):
        for f in fs:
            out.append(os.path.join(r, f))
    return sorted(out)


def epoch_to_utc(secs):
    return int(secs)


def local_to_utc(naive, zone, dst=None):
    """naive datetime (wall clock in zone) -> UTC epoch seconds.
    dst: None -> first occurrence for repeated times; True/False -> pick DST/standard occurrence."""
    d0 = naive.replace(tzinfo=zone, fold=0)
    d1 = naive.replace(tzinfo=zone, fold=1)
    o0, o1 = d0.utcoffset(), d1.utcoffset()
    if o0 == o1:
        d = d0
    elif o0 > o1:  # repeated wall-clock time
        d = d1 if dst is False else d0
    else:  # gap; shouldn't occur
        d = d0
    return int((d.replace(tzinfo=None) - d.utcoffset() - datetime(1970, 1, 1)).total_seconds())


def std_offset(zone, naive):
    d = naive.replace(tzinfo=zone, fold=0)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d


def iso_epoch(s):
    d = parse_iso(s)
    return int((d - EPOCH).total_seconds() // 1)


def norm_dir(s):
    s = s.strip().upper()
    if s in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if s in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    raise ValueError("bad direction %r" % s)


# ---------------------------------------------------------------- format readers
# each reader yields (punch_id, employee, direction, utc_epoch)
def read_abbr_csv(text, zone):
    header = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if "Badge" in row and "Punch" in row:
            header = {name: i for i, name in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda k: row[header[k]]
        dstr = g("Date")
        mo, dd, yy = dstr.split("/")
        tstr = g("Time").strip()
        up = tstr.upper()
        ampm = None
        if up.endswith("AM") or up.endswith("PM"):
            ampm = up[-2:]
            tstr = tstr[:-2].strip()
        h, mi, se = (int(x) for x in tstr.split(":"))
        if ampm:
            h = h % 12
            if ampm == "PM":
                h += 12
        naive = datetime(int(yy), int(mo), int(dd), h, mi, se)
        z = g("Zone").strip().upper() if "Zone" in header else ""
        dst = None
        if z.endswith("DT"):
            dst = True
        elif z.endswith("ST"):
            dst = False
        yield g("Record").strip(), g("Badge").strip(), norm_dir(g("Punch")), local_to_utc(naive, zone, dst)


def read_epoch_jsonl(text, zone):
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat") is True:
            continue
        if schema == 2:
            pid, emp, dr = o["punch_id"], o["employee"], o["direction"]
            ms = o["epoch_ms"]
            t = int(Fraction(str(ms)) // 1000) if not isinstance(ms, int) else ms // 1000
        else:
            pid, emp, dr = o["id"], o["emp"], o["dir"]
            if "ts_ms" in o:
                ms = o["ts_ms"]
                t = ms // 1000 if isinstance(ms, int) else int(Fraction(str(ms)) // 1000)
            else:
                ts = o["ts"]
                t = ts if isinstance(ts, int) else int(Fraction(str(ts)) // 1)
        yield str(pid).strip(), str(emp).strip(), norm_dir(dr), t


def read_offset_csv(text, zone):
    rdr = csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter=";", quotechar='"')
    for r in rdr:
        r = {k.strip(): v for k, v in r.items()}
        yield r["punch_id"].strip(), r["employee"].strip(), norm_dir(r["event"]), iso_epoch(r["timestamp"])


def read_legacy(text, zone):
    default = None
    cur = None
    for line in lines_of(text):
        t = line[0]
        if t == "H":
            off = line[13:18].strip()
            if off and off[0] in "+-" and len(off) == 5:
                sign = 1 if off[0] == "+" else -1
                cur = sign * (int(off[1:3]) * 3600 + int(off[3:5]) * 60)
            else:
                cur = None
        elif t == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = line[15]
            dt = line[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
            if cur is None:
                off = std_offset(zone, naive)
                secs = int(off.total_seconds())
            else:
                secs = cur
            utc = int((naive - datetime(1970, 1, 1)).total_seconds()) - secs
            yield pid, "E" + badge, norm_dir(dr), utc


def read_de_tsv(text, zone):
    header = None
    for line in lines_of(text):
        row = [c.strip() for c in line.split("\t")]
        if "Ausweis" in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda k: row[header[k]]
        dd, mo, yy = g("Datum").split(".")
        h, mi = g("Uhrzeit").split(":")[:2]
        naive = datetime(int(yy), int(mo), int(dd), int(h), int(mi))
        z = g("Zeitzone").upper() if "Zeitzone" in header else ""
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield g("Nr"), g("Ausweis"), norm_dir(g("Buchung")), local_to_utc(naive, zone, dst)


def read_local_csv(text, zone):
    rdr = csv.DictReader(io.StringIO("\n".join(lines_of(text))))
    for r in rdr:
        r = {k.strip(): v for k, v in r.items()}
        naive = datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"].strip(), r["employee_id"].strip(), norm_dir(r["direction"]), local_to_utc(naive, zone, None)


def read_local_jsonl(text, zone):
    for line in lines_of(text):
        o = json.loads(line)
        p = o.get("punch")
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S")
        yield str(p["id"]).strip(), str(p["badge"]).strip(), norm_dir(p["type"]), local_to_utc(naive, zone, None)


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def round_punch(t, zone):
    """Round to nearest 6-minute local mark (half up), keeping the offset at the original instant."""
    off = int(datetime.fromtimestamp(t, zone).utcoffset().total_seconds())
    local = t + off
    r = ((local + 180) // 360) * 360
    return t + (r - local)


def main(indir, outfile):
    period = json.load(open(os.path.join(indir, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = iso_epoch(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(indir, "sites.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    with open(os.path.join(indir, "employees.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    with open(os.path.join(indir, "rates.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(Decimal(r["hourly_rate"].strip()))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: (site, id) -> [employee, dir, utc]
    punches = {}
    ever = set()
    for site, (zone, fmt) in sites.items():
        reader = READERS[fmt]
        for path in all_files(os.path.join(indir, "exports", site)):
            for pid, emp, dr, t in reader(read_text(path), zone):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp, dr, t]

    # 2. corrections
    corr = []
    for path in all_files(os.path.join(indir, "corrections")):
        text = read_text(path)
        ls = lines_of(text)
        if not ls:
            continue
        for r in csv.DictReader(io.StringIO("\n".join(ls))):
            r = {(k or "").strip(): (v or "").strip() for k, v in r.items()}
            corr.append(r)
    for r in corr:
        r["_t"] = iso_epoch(r["issued_at"])
    corr = [r for r in corr if r["_t"] <= cutoff]
    corr.sort(key=lambda r: (r["_t"], r["correction_id"]))
    voided = set()
    applied = 0
    for r in corr:
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and key not in voided:
                punches[key][2] = iso_epoch(r["time"])
                applied += 1
        elif act == "add":
            if key not in ever and r["site"] in sites:
                ever.add(key)
                punches[key] = [r["employee"], norm_dir(r["type"]), iso_epoch(r["time"])]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, t) in punches.items():
        if emp in employees:
            byemp.setdefault(emp, []).append((t, 0 if dr == "OUT" else 1, site, pid, dr))

    def workday(rt, emp):
        hz = sites[employees[emp]][0]
        return datetime.fromtimestamp(rt, hz).date()

    dup_count = 0
    open_count = 0
    orphan_count = 0
    shifts = {e: [] for e in employees}  # (in_rt, out_rt, site, workday)

    for emp, plist in byemp.items():
        plist.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for p in plist:
            t, _, site, pid, dr = p
            if last is not None and last[4] == dr and t - last[0] <= 300:
                rt = round_punch(t, sites[site][0])
                if pstart <= workday(rt, emp) <= pend:
                    dup_count += 1
                continue
            kept.append(p)
            last = p
        # rounding
        rk = [(round_punch(p[0], sites[p[2]][0]), p[2], p[4]) for p in kept]
        pending = None
        for rt, site, dr in rk:
            if dr == "IN":
                if pending is not None:
                    if pstart <= workday(pending[0], emp) <= pend:
                        open_count += 1
                pending = (rt, site)
            else:
                if pending is not None and rt - pending[0] <= 16 * 3600:
                    shifts[emp].append((pending[0], rt, pending[1], workday(pending[0], emp)))
                    pending = None
                else:
                    if pending is not None:
                        if pstart <= workday(pending[0], emp) <= pend:
                            open_count += 1
                        pending = None
                    if pstart <= workday(rt, emp) <= pend:
                        orphan_count += 1
        if pending is not None and pstart <= workday(pending[0], emp) <= pend:
            open_count += 1

    def night_minutes(a, b, zone):
        n = 0
        t = a
        o_a = zone.utcoffset(datetime.fromtimestamp(a, zone).replace(tzinfo=None)) if False else None
        cache_off = None
        while t < b:
            off = int(datetime.fromtimestamp(t, zone).utcoffset().total_seconds())
            local = (t + off) % 86400
            if local >= 22 * 3600 or local < 6 * 3600:
                n += 1
            t += 60
        return n

    result_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tot_gross = 0
    for emp in sorted(employees):
        sl = sorted((s for s in shifts[emp] if pstart <= s[3] <= pend), key=lambda s: (s[0], s[1]))
        day_cum = {}
        week_cum = {}
        paid_sum = ot_sum = night_sum = 0
        pay = Fraction(0)
        for a, b, site, wd in sl:
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, sites[site][0]), paid)
            before = day_cum.get(wd, 0)
            after = before + paid
            day_cum[wd] = after
            dot = max(0, after - 480) - max(0, before - 480)
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            wb = week_cum.get(wk, 0)
            wa = wb + nd
            week_cum[wk] = wa
            wot = max(0, wa - 2400) - max(0, wb - 2400)
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rt_ in rates.get(emp, []):
                if eff <= wd:
                    rate = rt_
            if rate is None:
                rate = Fraction(0)
            pay += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            paid_sum += paid
            ot_sum += ot
            night_sum += night
        cents = pay * 100
        c = int((cents + Fraction(1, 2)) // 1)
        gross = "%d.%02d" % (c // 100, c % 100)
        result_emps[emp] = {"shifts": len(sl), "paid_minutes": paid_sum, "overtime_minutes": ot_sum,
                            "night_minutes": night_sum, "gross": gross}
        tot["shifts"] += len(sl)
        tot["paid_minutes"] += paid_sum
        tot["overtime_minutes"] += ot_sum
        tot["night_minutes"] += night_sum
        tot_gross += c
    tot["gross"] = "%d.%02d" % (tot_gross // 100, tot_gross % 100)

    out = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": result_emps,
        "exceptions": {"open_shifts": open_count, "orphan_outs": orphan_count,
                       "duplicates_dropped": dup_count, "corrections_applied": applied},
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
